import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { loadTheme, saveTheme, THEME_STORAGE_KEY } from './theme-storage';

function makeStorage(initial: Record<string, string> = {}) {
  const data: Record<string, string> = { ...initial };
  return {
    data,
    getItem: (k: string) => (k in data ? data[k] : null),
    setItem: (k: string, v: string) => { data[k] = String(v); },
  };
}

describe('theme storage', () => {
  beforeEach(() => { vi.stubGlobal('window', {}); });
  afterEach(() => { vi.unstubAllGlobals(); });

  it('defaults to light when nothing stored', () => {
    (globalThis as any).window.localStorage = makeStorage();
    expect(loadTheme()).toBe('light');
  });
  it('restores each valid stored value', () => {
    for (const t of ['light', 'dark', 'system']) {
      (globalThis as any).window.localStorage = makeStorage({ [THEME_STORAGE_KEY]: t });
      expect(loadTheme()).toBe(t);
    }
  });
  it('falls back on invalid stored value', () => {
    (globalThis as any).window.localStorage = makeStorage({ [THEME_STORAGE_KEY]: 'blue' });
    expect(loadTheme()).toBe('light');
  });
  it('falls back when localStorage throws', () => {
    (globalThis as any).window.localStorage = { getItem: () => { throw new Error('denied'); }, setItem: () => { throw new Error('denied'); } };
    expect(loadTheme()).toBe('light');
    expect(() => saveTheme('dark')).not.toThrow();
  });
  it('round-trips through saveTheme/loadTheme', () => {
    const s = makeStorage();
    (globalThis as any).window.localStorage = s;
    saveTheme('dark');
    expect(s.data[THEME_STORAGE_KEY]).toBe('dark');
    expect(loadTheme()).toBe('dark');
  });
});
EOF
